// apply-update-9.js
// Run with: node apply-update-9.js
//
// Replaces the abstract drifting-shapes graphic in the homepage "Who we
// are" section with a real photo (framed in the site's notch-corner style),
// and removes the now-unused AmbientNotches component + its CSS.
//
// New: public/studio/who-we-are.jpg
// Changed: src/components/WhoWeAre.tsx, src/app/globals.css
// Deleted: src/components/AmbientNotches.tsx

const fs = require("fs");
const path = require("path");

const files = [
  {
    path: "src/app/globals.css",
    base64: "",
  },
  {
    path: "src/components/WhoWeAre.tsx",
    base64: "",
  },
  {
    path: "public/studio/who-we-are.jpg",
    base64: "",
  },
];

const deletedFiles = [
  "src/components/AmbientNotches.tsx",
];

for (const file of files) {
  const fullPath = path.join(__dirname, file.path);
  fs.mkdirSync(path.dirname(fullPath), { recursive: true });
  fs.writeFileSync(fullPath, Buffer.from(file.base64, "base64"));
  console.log("Updated", file.path);
}

for (const relPath of deletedFiles) {
  const fullPath = path.join(__dirname, relPath);
  if (fs.existsSync(fullPath)) {
    fs.unlinkSync(fullPath);
    console.log("Deleted", relPath);
  }
}

console.log("\nDone.");
